// File storage for generated audio (and khata photos in Phase 4). Local disk
// for now; Supabase Storage later behind the same interface.
import { mkdir, readFile, stat, writeFile } from "node:fs/promises";
import { join, resolve } from "node:path";

export interface FileStorage {
  exists(folder: string, name: string): Promise<boolean>;
  put(folder: string, name: string, data: Buffer): Promise<void>;
  get(folder: string, name: string): Promise<Buffer | null>;
}

/** Names are generated by us (hashes); reject anything that could escape the folder. */
const SAFE_NAME = /^[a-zA-Z0-9_-]+\.[a-z0-9]{2,5}$/;

export function localStorage(rootDir: string): FileStorage {
  const root = resolve(rootDir);
  const path = (folder: string, name: string) => {
    if (!/^[a-z-]+$/.test(folder) || !SAFE_NAME.test(name)) throw new Error("invalid file name");
    return join(root, folder, name);
  };
  return {
    async exists(folder, name) {
      try {
        return (await stat(path(folder, name))).isFile();
      } catch {
        return false;
      }
    },
    async put(folder, name, data) {
      await mkdir(join(root, folder), { recursive: true });
      await writeFile(path(folder, name), data);
    },
    async get(folder, name) {
      try {
        return await readFile(path(folder, name));
      } catch {
        return null;
      }
    },
  };
}

export const isSafeFileName = (name: string) => SAFE_NAME.test(name);
